from collections import Counter

def _regular_missing_rows(grid, value, axis):
    n = len(grid) if axis == 0 else len(grid[0])
    indices = [i for i in range(n) if all((grid[i][j] != value if axis == 0 else grid[j][i] != value) for j in range(len(grid[0]) if axis == 0 else len(grid)))]
    if len(indices) < 2:
        return None
    gaps = [b-a for a,b in zip(indices, indices[1:])]
    if len(set(gaps)) != 1:
        return None
    return indices

def transform(grid):
    h, w = len(grid), len(grid[0])
    candidates = []
    for value in set(v for row in grid for v in row):
        rows = _regular_missing_rows(grid, value, 0)
        cols = _regular_missing_rows(grid, value, 1)
        if rows and cols:
            candidates.append((len(rows)+len(cols), value, rows, cols))
    _, fill, rows, cols = max(candidates)
    intersections = [grid[r][c] for r in rows for c in cols]
    line_color = Counter(v for v in intersections if v != fill).most_common(1)[0][0]
    out = []
    for r0,r1 in zip(rows, rows[1:]):
        line=[]
        for c0,c1 in zip(cols, cols[1:]):
            vals=[grid[r0][c0],grid[r0][c1],grid[r1][c0],grid[r1][c1]]
            line.append(vals[0] if vals.count(vals[0]) == 4 and vals[0] != fill and vals[0] != line_color else fill)
        out.append(line)
    while out and all(v == fill for v in out[0]): out.pop(0)
    while out and all(v == fill for v in out[-1]): out.pop()
    if out:
        while out[0] and all(row[0] == fill for row in out):
            for row in out: row.pop(0)
        while out[0] and all(row[-1] == fill for row in out):
            for row in out: row.pop()
    return out

